5	// Axis domains use full-chart coordinates, independent of viewport size.
6	export function axisRange(domain, a, b) {
7	  const lo = Math.max(domain[0], Math.min(a, b)), hi = Math.min(domain[1], Math.max(a, b));
8	  return hi > lo ? [lo, hi] : [...domain];
9	}
10	export function rangePosition(value, domain, width = 100) {
11	  return (value - domain[0]) / (domain[1] - domain[0] || 1) * width;
12	}
13	// Foreground work is active time even when main requests are far apart.
14	export function timeScale(times, width, foreground = []) {
15	  const valid = times.filter(Number.isFinite);
16	  const evenly = () => ({ x: times.map((_, i) => markerPercent(i, times.length) * width / 100), breaks: [] });
17	  if (valid.length < 2) return evenly();
18	  const filled = timelineTimes(times);
19	  const gaps = filled.slice(1).map((t, i) => t - filled[i]);
20	  const idle = gaps.map((g, i) => g > 15 * 60000 && !foreground.some(([a, b]) => a <= filled[i + 1] && b >= filled[i]));
21	  const long = idle.filter(Boolean).length;
22	  const duration = gaps.reduce((n, g, i) => n + (idle[i] ? 0 : g), 0);
23	  if (!duration) return evenly();
24	  // Dense breaks share the same budget; nearby marks are merged below.
25	  const markWidth = Math.max(2, Math.min(12, .2 * width / Math.max(1, long)));
26	  const breakWidth = Math.min(markWidth, .2 * width / Math.max(1, long));
27	  const available = width - long * breakWidth;
28	  const x = [0], breaks = [];
29	  gaps.forEach((gap, i) => {
30	    const size = idle[i] ? breakWidth : gap / duration * available;
31	    if (idle[i]) {
32	      const center = x[i] + size / 2;
33	      if (!breaks.length || center - breaks.at(-1) >= 4) breaks.push(center);
34	    }
35	    x.push(x[i] + size);
36	  });
37	  return { x, breaks };
38	}
